export function observeImageLocalDisplayRotation(
  zoom: ImageLocalDisplayZoomObservation | null,
  rotationIndex: number,
): ImageLocalDisplayRotationObservation | null {
  if (zoom === null) return null;
  verifyImageLocalDisplayZoomObservation(zoom);
  const rotationDegrees = IMAGE_LOCAL_DISPLAY_ROTATION_DEGREES[rotationIndex];
  if (rotationDegrees === undefined) {
    throw new Error('runtime-media-image-local-display-rotation-mismatch');
  }
  const swapsAxes = rotationIndex % 2 === 1;
  const imageTransform = rotationDegrees === 0
    ? 'none'
    : rotationDegrees === 90
      ? `translate(${zoom.cssHeightPx}px, 0px) rotate(90deg)`
      : rotationDegrees === 180
        ? `translate(${zoom.cssWidthPx}px, ${zoom.cssHeightPx}px) rotate(180deg)`
        : `translate(0px, ${zoom.cssWidthPx}px) rotate(270deg)`;
  return {
    rotationIndex,
    rotationDegrees,
    frameCssWidthPx: swapsAxes ? zoom.cssHeightPx : zoom.cssWidthPx,
    frameCssHeightPx: swapsAxes ? zoom.cssWidthPx : zoom.cssHeightPx,
    imageTransform,
